<script setup lang="ts">
import type { ApiEnvelope } from '~/types/api'
import type { Plan, Subscription, Payment } from '~/types/billing'
import { money, billingDate } from '~/utils/billing'
definePageMeta({layout:'dashboard',middleware:'auth'})
useSeoMeta({title:'Billing & subscription'})
const {request}=useApi(),route=useRoute()
interface Billing {plan:Plan;subscription:Subscription|null;history:Subscription[];payments:Payment[];links_used:number;stripe_enabled:boolean;portal_available:boolean}
const {data,pending,error,refresh}=await useAsyncData('customer-billing',()=>request<ApiEnvelope<Billing>>('billing'))
const {data:plans}=await useAsyncData('billing-plans',()=>request<ApiEnvelope<Plan[]>>('plans'))
const busy=ref(false),failure=ref(''),interval=ref<'month'|'year'>('month')
async function go(path:string,body?:Record<string,unknown>){busy.value=true;failure.value='';try{const result=await request<ApiEnvelope<{url:string}>>(path,{method:'POST',body});await navigateTo(result.data.url,{external:true})}catch(e:any){failure.value=e?.data?.message||'Billing is temporarily unavailable.';busy.value=false}}
</script>
<template><div class="dashboard-page"><div class="flex justify-between gap-3"><div><p class="eyebrow">Your account</p><h1 class="page-title mt-2">Billing & subscription</h1><p class="mt-2 text-text-secondary">Your plan, usage, and billing history in one place.</p></div><button class="btn-secondary" :disabled="pending" @click="refresh()">Refresh</button></div><p v-if="route.query.checkout==='success'" class="mt-6 rounded-lg bg-brand-light p-4 text-brand" role="status">Thanks. Your payment is being confirmed. Refresh to see your updated subscription; access changes only after confirmation from Stripe.</p><p v-if="route.query.checkout==='cancelled'" class="mt-6 rounded-lg bg-surface2 p-4" role="status">Checkout was cancelled. Your current plan has not changed.</p><p v-if="failure" class="mt-5 text-danger" role="alert">{{ failure }}</p><LoadingState v-if="pending"/><p v-else-if="error" class="surface mt-6 p-6" role="alert">Unable to load billing. <button class="text-brand" @click="refresh()">Try again</button></p><template v-else-if="data"><div class="mt-7 grid gap-5 md:grid-cols-2"><section class="surface p-6"><p class="text-xs text-text-muted">Current plan</p><h2 class="mt-2 text-2xl font-semibold">{{ data.data.plan?.name || 'Free' }}</h2><p class="mt-3 text-text-secondary">{{ data.data.links_used }} / {{ data.data.plan?.link_limit??'unlimited' }} links used</p><p v-if="data.data.subscription" class="mt-3 text-sm">{{ data.data.subscription.effective_status }} · Current period ends {{ billingDate(data.data.subscription.ends_at) }}</p><p v-if="data.data.subscription?.cancel_at_period_end" class="mt-2 text-warning">Your subscription will end at the end of this period.</p><button v-if="data.data.portal_available" class="btn-primary mt-5" :disabled="busy" @click="go('billing/portal')">Manage Stripe billing</button><NuxtLink v-else to="/contact" class="btn-secondary mt-5">Contact billing support</NuxtLink></section><section class="surface p-6"><h2 class="font-semibold">Payment details</h2><p class="mt-3 text-sm text-text-secondary">Stripe securely handles card details, recurring payments, and Stripe invoices. You can manage payment methods and cancellation in its billing portal.</p><p v-if="!data.data.stripe_enabled" class="mt-4 rounded-lg bg-warning-bg p-3 text-sm text-warning">Online payments are not enabled yet. Contact us to arrange a subscription.</p></section></div><section class="mt-8"><div class="flex items-center justify-between"><h2 class="text-lg font-semibold">Available plans</h2><label class="flex items-center gap-2 text-sm">Billing interval<select v-model="interval" class="input w-auto"><option value="month">Monthly</option><option value="year">Yearly</option></select></label></div><div class="mt-4 grid gap-4 lg:grid-cols-3"><article v-for="plan in plans?.data" :key="plan.id" class="surface p-6"><h3 class="font-semibold">{{ plan.name }}</h3><p class="mt-4 text-2xl font-bold">{{ money(interval==='month'?plan.monthly_price:plan.yearly_price,plan.currency) }}<span class="text-xs font-normal"> / {{ interval }}</span></p><p class="mt-3 text-sm text-text-secondary">{{ plan.description }}</p><button v-if="(interval==='month'?plan.checkout_monthly:plan.checkout_yearly) && !data.data.subscription" class="btn-primary mt-5 w-full" :disabled="busy" @click="go('billing/checkout',{plan_id:plan.id,interval})">{{ busy?'Connecting…':'Continue to Stripe' }}</button><NuxtLink v-else-if="!plan.is_default" to="/contact" class="btn-secondary mt-5 w-full">Contact us</NuxtLink><span v-else class="badge-brand mt-5">Included</span></article></div></section><section class="surface mt-8 overflow-x-auto"><h2 class="p-5 font-semibold">Subscription history</h2><table class="admin-table"><thead><tr><th>Plan</th><th>Status</th><th>Amount</th><th>Period</th><th>Source</th></tr></thead><tbody><tr v-for="subscription in data.data.history" :key="subscription.id"><td>{{ subscription.plan.name }}</td><td>{{ subscription.effective_status }}</td><td>{{ money(subscription.amount,subscription.currency) }}</td><td>{{ billingDate(subscription.starts_at) }} – {{ billingDate(subscription.ends_at) }}</td><td>{{ subscription.provider }}</td></tr><tr v-if="!data.data.history.length"><td colspan="5" class="py-8 text-center">You are using the Free plan.</td></tr></tbody></table></section><section class="surface mt-6 overflow-x-auto"><h2 class="p-5 font-semibold">Manual payment history</h2><table class="admin-table"><thead><tr><th>Reference</th><th>Amount</th><th>Date</th><th>Status</th></tr></thead><tbody><tr v-for="payment in data.data.payments" :key="payment.id"><td>{{ payment.reference }}</td><td>{{ money(payment.amount,payment.currency) }}</td><td>{{ billingDate(payment.paid_at) }}</td><td>{{ payment.status }}</td></tr><tr v-if="!data.data.payments.length"><td colspan="4" class="py-8 text-center">No manual payments. Stripe payment history is available in Manage Stripe billing.</td></tr></tbody></table></section></template></div></template>
